document.querySelectorAll(".nav").forEach(btn=>btn.addEventListener("click",()=>{document.querySelectorAll(".nav").forEach(x=>x.classList.remove("active"));btn.classList.add("active");document.querySelectorAll(".page").forEach(p=>p.classList.remove("active"));$("page-"+btn.dataset.tab).classList.add("active");if(btn.dataset.tab==="terminal")setTimeout(()=>Object.keys(lastResult||{}).length&&drawAll(),20)}));
function parseYahoo(json){const r=json.chart?.result?.[0];if(!r)throw Error(json.chart?.error?.description||"No data returned. Check the ticker and date range.");const q=r.indicators.quote[0],adj=r.indicators.adjclose?.[0]?.adjclose||[];return r.timestamp.map((t,i)=>({date:new Date(t*1000).toISOString().slice(0,10),open:q.open[i],high:q.high[i],low:q.low[i],close:q.close[i],adjClose:adj[i]??q.close[i],volume:q.volume[i]??0})).filter(x=>[x.open,x.high,x.low,x.close].every(Number.isFinite))}
async function getYahoo(symbol,start,end,interval){const p1=Math.floor(new Date(start+"T00:00:00Z").getTime()/1000),p2=Math.floor(new Date(end+"T23:59:59Z").getTime()/1000)+1;const hosts=["query1.finance.yahoo.com","query2.finance.yahoo.com"];let lastError=null;for(const host of hosts){const url="https://"+host+"/v8/finance/chart/"+encodeURIComponent(symbol)+"?period1="+p1+"&period2="+p2+"&interval="+interval+"&events=div%2Csplits";try{const res=await fetch("https://proxy.cors.dev/"+url,{method:"GET",mode:"cors",credentials:"omit",headers:{Accept:"application/json"}});const proxyCode=res.headers.get("X-Cors-Error");if(!res.ok){const body=(await res.text()).slice(0,220);throw Error("HTTP "+res.status+(proxyCode?" · "+proxyCode:"")+(body?" · "+body:""))}const payload=await res.json();const rows=parseYahoo(payload);if(!rows.length)throw Error("Yahoo returned no OHLCV rows for "+symbol+" in the selected date range.");return rows}catch(e){lastError=e}}throw Error("Unable to load "+symbol+" from Yahoo Finance. "+(lastError?.message||"Unknown provider error")+". Check your connection/date range, then retry. This free historical-data relay can be temporarily rate-limited.")}
async function getStooq(symbol,start,end,interval){if(interval!=="1d")throw Error("Stooq browser fallback currently supports daily bars only.");let s=symbol.toLowerCase().replace(".ns",".in").replace(".bo",".in");if(!s.includes("."))s+=".us";const u="https://stooq.com/q/d/l/?s="+encodeURIComponent(s)+"&d1="+start.replaceAll("-","")+"&d2="+end.replaceAll("-","")+"&i=d";const res=await fetch(u);if(!res.ok)throw Error("Stooq request failed ("+res.status+").");const txt=await res.text();if(!txt||txt.startsWith("No data"))throw Error("Stooq returned no data for this symbol.");return csvToBars(txt)}
function normaliseBars(rows){const clean=rows.map(r=>({date:String(r.date).slice(0,10),open:+r.open,high:+r.high,low:+r.low,close:+r.close,adjClose:Number.isFinite(+r.adjClose)?+r.adjClose:+r.close,volume:Number.isFinite(+r.volume)?+r.volume:0})).filter(r=>r.date&&[r.open,r.high,r.low,r.close].every(Number.isFinite));clean.sort((a,b)=>a.date.localeCompare(b.date));const seen=new Set();for(const r of clean){if(seen.has(r.date))throw Error("Duplicate date detected: "+r.date);seen.add(r.date);if(r.open<=0||r.high<=0||r.low<=0||r.close<=0||r.high<Math.max(r.open,r.close,r.low)||r.low>Math.min(r.open,r.close,r.high))throw Error("Invalid OHLC prices on "+r.date)}if(clean.length<35)throw Error("At least 35 valid bars are required; received "+clean.length+".");return clean}
function csvToBars(text){const parsed=Papa.parse(text.trim(),{header:true,skipEmptyLines:true,dynamicTyping:true});if(parsed.errors.length)throw Error("CSV parse issue: "+parsed.errors[0].message);const map={};for(const k of Object.keys(parsed.meta.fields||[]))map[k.toLowerCase().trim()]=k;const pick=(r,k)=>r[map[k]];for(const k of ["date","open","high","low","close"])if(!map[k])throw Error("CSV missing required column: "+k);return normaliseBars(parsed.data.map(r=>({date:pick(r,"date"),open:pick(r,"open"),high:pick(r,"high"),low:pick(r,"low"),close:pick(r,"close"),adjClose:map["adj close"]?pick(r,"adj close"):pick(r,"close"),volume:map.volume?pick(r,"volume"):0})))}
function sampleBars(){const out=[];let p=100;for(let i=0;i<1100;i++){let t=new Date(Date.UTC(2020,0,1+i));if(t.getUTCDay()===0||t.getUTCDay()===6)continue;let cyc=Math.sin(i/43)*.002+Math.sin(i/125)*.001;let ch=.00035+cyc+(Math.random()-.49)*.018;p*=1+ch;let o=p*(1+(Math.random()-.5)*.006),c=p,h=Math.max(o,c)*(1+Math.random()*.012),l=Math.min(o,c)*(1-Math.random()*.012);out.push({date:t.toISOString().slice(0,10),open:o,high:h,low:l,close:c,adjClose:c,volume:100000+Math.round(Math.random()*900000)})}return out}
async function loadData(){const sym=$("ticker").value.trim().toUpperCase(),source=$("source").value;const start=$("startDate").value,end=$("endDate").value;if(!sym&&source!=="sample")return setStatus("Enter a ticker",true);if(start>=end)return setStatus("Start date must be before end date",true);setStatus("Fetching historical bars…");$("loadData").disabled=true;try{let rows;if(source==="sample"){rows=sampleBars();sourceMeta="Synthetic sample data (not a tradable security)"}else if(source==="stooq"){rows=await getStooq(sym,start,end,$("interval").value);sourceMeta="Stooq free historical CSV"}else{rows=await getYahoo(sym,start,end,$("interval").value);sourceMeta="Yahoo Finance chart API — historical"}bars=normaliseBars(rows);lastSymbol=sym||"SAMPLE";setStatus(bars.length+" bars loaded");renderDataSummary();drawPrice();}catch(e){setStatus(e.message,true)}finally{$("loadData").disabled=false}}
