async function drawLiveProgressCharts(p){
 if(!window.Plotly)return;
 const visible=bars.slice(0,p.processed),dates=visible.map(x=>x.date);
 const series=p.series,eq=series.map(x=>x.equity);
 const candles={x:dates,open:visible.map(x=>x.open),high:visible.map(x=>x.high),low:visible.map(x=>x.low),close:visible.map(x=>x.close),type:"candlestick",name:lastSymbol,increasing:{line:{color:"#b1f36c"}},decreasing:{line:{color:"#ff747e"}}};
 $("chartTicker").textContent=lastSymbol+" · "+p.processed.toLocaleString()+"/"+p.total.toLocaleString()+" BARS";
 const initialCapital=Number($("capital").value)||100000;const buyHold=visible.map(x=>initialCapital*x.close/visible[0].close);
 const equityTraces=[
  {x:dates,y:eq,type:"scatter",mode:"lines",name:"Strategy",line:{color:"#b1f36c",width:2}},
  {x:dates,y:buyHold,type:"scatter",mode:"lines",name:"Buy & hold",line:{color:"#7188a7",width:1,dash:"dot"}}
 ];
 let peak=Number($("capital").value)||100000;
 const dd=[];
 eq.forEach(value=>{peak=Math.max(peak,value);dd.push((value/peak-1)*100)});
 const drawdownTrace={x:dates,y:dd,type:"scatter",mode:"lines",fill:"tozeroy",name:"Drawdown",line:{color:"#ff747e",width:1.5}};
 const trades=p.tradeRows||[];
 const tradeTrace={x:trades.map((t,i)=>"T"+(i+1)),y:trades.map(t=>t.ret*100),type:"bar",name:"Trade return",marker:{color:trades.map(t=>t.pnl>=0?"#b1f36c":"#ff747e")}};
 const pendingLayout={annotations:[{text:"Waiting for first closed trade…",xref:"paper",yref:"paper",x:.5,y:.5,showarrow:false,font:{color:"#8391a5",size:10}}]};
 const tradeLayout=trades.length?{yaxis:{title:"Return (%)"},showlegend:false}:{yaxis:{title:"Return (%)"},showlegend:false,...pendingLayout};
 await Promise.all([
  plotLive("priceChart",[candles],{xaxis:{rangeslider:{visible:false},gridcolor:"#202b3a"},yaxis:{title:"Price"}}),
  plotLive("equityChart",equityTraces,{yaxis:{title:"Portfolio value"}}),
  plotLive("drawdownChart",[drawdownTrace],{yaxis:{title:"Drawdown (%)"}}),
  plotLive("tradeChart",[tradeTrace],tradeLayout)
 ]);
}
function defaultBuilderRule(kind,side="long"){return defaultRule(kind==="entry"||kind==="shortEntry"?"entry":"exit",side)}
